let me=0;
const $=s=>document.querySelector(s),KEY='solaris-fronteira-v1',UIKEY='solaris-fronteira-display';
let world=null,g,selected=0,target=null,amount=54,panel=null,dispatch=false,upgradeDetails=false,fleetFilter='all',starFilter='all',eventsTab='all',battleFocus=null,routeEditor=false,autoTarget=null,autoReserve=0,picking=false,toastTimer;
let turnPlayback=null,turnFrame=0,creditTimer=0;
let prefs={names:true,ships:true,infrastructure:false,routes:true,range:true};
try{const saved=restoreGame(JSON.parse(localStorage.getItem(KEY)));if(saved)world=saved;const p=JSON.parse(localStorage.getItem(UIKEY));for(const k in prefs)if(typeof p?.[k]==='boolean')prefs[k]=p[k];}catch{}
if(!world)world=newGame();
g=playerView(world,0);selected=g.stars.find(s=>s.owner===me)?.id??0;
const camera={x:505,y:300,zoom:1};const color=o=>factionColors[o]??'#8996a6';const ownerName=o=>o===null?'Desconhecida':o===-1?'Neutra':online.room?`${empireLabel(online.room,o)}${o===me?' · você':''}`:o===me?'Você':o===0?'Sol':factionName(o);const htmlOwnerName=o=>escapeHTML(ownerName(o));const isMobile=()=>innerWidth<=600;
function save(){if(online.room)return;try{localStorage.setItem(KEY,JSON.stringify(world));}catch{notify('Não foi possível salvar. Mantenha esta aba aberta.');}}
function notify(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3400);}
async function act(fn){try{await fn();save();render();}catch(e){notify(e.message);}}
function activePanel(name){return panel===name?'active':'';}
function closePanel(){picking=false;panel=null;routeEditor=false;upgradeDetails=false;dispatch=false;target=null;render();}
function openPanel(name){picking=false;if(panel===name&&name!=='star'){closePanel();return;}panel=name;if(name!=='star'){routeEditor=false;upgradeDetails=false;dispatch=false;target=null;}render();}
function selectStar(id){picking=false;selected=id;routeEditor=false;target=null;dispatch=false;amount=Math.max(1,g.stars[id].ships);panel='star';render();centerOn(g.stars[id]);}
function fitZoom(){const r=$('#map').getBoundingClientRect(),b=mapBounds(g);return Math.min((r.width-60)/b.width,(r.height-100)/b.height);}
function fit(){const b=mapBounds(g);camera.zoom=fitZoom();camera.x=b.x;camera.y=b.y;drawMap();}
function startView(){fit();if(isMobile()){const home=g.stars.find(s=>s.owner===me)||g.stars[0],bounds=mapBounds(g);camera.zoom=.7;camera.x=home.x+(bounds.x-home.x)*.3;camera.y=home.y+(bounds.y-home.y)*.3;drawMap();}}
function centerOn(s){const r=$('#map').getBoundingClientRect(),p=$('#panel').getBoundingClientRect();let px=r.width/2,py=r.height/2;if(panel&&!picking){if(isMobile())py=Math.max(75,(r.height-(panelTargetHeight||p.height))/2);else px=(p.width+28+r.width)/2;}camera.x=s.x-(px-r.width/2)/camera.zoom;camera.y=s.y-(py-r.height/2)/camera.zoom;drawMap();}
function zoomBy(factor,point){const r=$('#map').getBoundingClientRect();const px=point?point.x-r.left:r.width/2,py=point?point.y-r.top:r.height/2;const wx=camera.x+(px-r.width/2)/camera.zoom,wy=camera.y+(py-r.height/2)/camera.zoom;camera.zoom=Math.max(Math.min(.25,fitZoom()),Math.min(3,camera.zoom*factor));camera.x=wx-(px-r.width/2)/camera.zoom;camera.y=wy-(py-r.height/2)/camera.zoom;drawMap();}
function drawMap(){const svg=$('#map'),r=svg.getBoundingClientRect(),w=r.width/camera.zoom,h=r.height/camera.zoom;svg.setAttribute('viewBox',`${camera.x-w/2} ${camera.y-h/2} ${w} ${h}`);const unit=1/camera.zoom,glyph=Math.max(.45,Math.min(1,camera.zoom/.48)),s=g.stars[selected],view=turnPlayback?.phase==='travel'?turnPlayback.view:g;let out='';
for(let i=0;i<170;i++){const x=(i*277+71)%2100-500,y=(i*173+19)%1500-400;out+=`<circle cx="${x}" cy="${y}" r="${(i%9===0?1.4:.65)*unit}" fill="#d8e8ff" opacity="${i%9===0?.6:.2}"/>`;}
if(panel==='star'&&s.owner===me&&prefs.range&&g.winner===null){out+=`<circle class="selected-range" pointer-events="none" cx="${s.x}" cy="${s.y}" r="${RANGE}" fill="#348bff" fill-opacity=".025" stroke="#5798d9" stroke-opacity=".42" stroke-width="${unit}" stroke-dasharray="${6*unit} ${5*unit}"/>`;}
if(routeEditor&&autoTarget!==null){const t=g.stars[autoTarget];out+=`<line x1="${s.x}" y1="${s.y}" x2="${t.x}" y2="${t.y}" stroke="#68e9c9" stroke-width="${1.5*unit}" stroke-dasharray="${5*unit} ${5*unit}"/>`;}
if(prefs.routes)for(const route of g.autoRoutes.filter(r=>r.owner===me&&r.enabled)){const a=g.stars[route.from],b=g.stars[route.to];out+=`<g class="automatic-route"><line x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}" stroke="#00bc8c" stroke-opacity=".5" stroke-width="${unit}" stroke-dasharray="${2*unit} ${6*unit}"/><path d="M-5 -4 L2 0 L-5 4" fill="none" stroke="#68e9c9" stroke-width="1.5" transform="translate(${(a.x+b.x)/2},${(a.y+b.y)/2}) scale(${unit}) rotate(${Math.atan2(b.y-a.y,b.x-a.x)*180/Math.PI})"/></g>`;}
if(dispatch&&target!==null){const t=g.stars[target];out+=`<line x1="${s.x}" y1="${s.y}" x2="${t.x}" y2="${t.y}" stroke="#fff" stroke-width="${1.5*unit}" stroke-dasharray="${6*unit} ${5*unit}"/>`;}
for(const f of [...g.fleets,...g.orders]){if(turnPlayback?.phase==='travel'&&!g.orders.includes(f))continue;const reserved=g.orders.includes(f),known=Number.isInteger(f.from)&&Number.isInteger(f.to),a=known?g.stars[f.from]:null,b=known?g.stars[f.to]:null,{x,y}=fleetPosition(g,f),heading=known?Math.atan2(b.y-a.y,b.x-a.x)*180/Math.PI:f.heading;if(prefs.routes&&known)out+=`<line class="fleet-route" data-route-fleet="${f.id}" x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}" stroke="${color(f.owner)}" stroke-opacity=".7" stroke-width="${unit*1.5}" ${reserved?`stroke-dasharray="${5*unit} ${5*unit}"`:''}/>`;if(prefs.routes&&!known&&Number.isFinite(heading))out+=`<path class="fleet-direction" data-direction-fleet="${f.id}" d="M18 0 H58 M52 -4 L58 0 L52 4" fill="none" stroke="${color(f.owner)}" stroke-width="1.5" stroke-opacity=".85" pointer-events="none" transform="translate(${x},${y}) scale(${unit}) rotate(${heading})"/>`;out+=`<g class="map-fleet" data-fleet="${f.id}" role="button" tabindex="0" aria-label="Frotas: ${f.ships} naves de ${htmlOwnerName(f.owner)}${known?` para ${b.name}`:''}" transform="translate(${x},${y}) scale(${unit})"><circle r="15" fill="#071724" stroke="${color(f.owner)}" stroke-width="2"/><path d="M0 -8 L6 6 L0 3 L-6 6 Z" fill="white" transform="rotate(${Number.isFinite(heading)?heading+90:0})"/>${prefs.ships?`<text x="0" y="29" text-anchor="middle" font-size="12" fill="white">${f.ships}</text>`:''}</g>`;}

for(const b of view.stars){const sel=panel==='star'&&selected===b.id,chosen=(dispatch&&target===b.id)||(routeEditor&&autoTarget===b.id),reachable=(dispatch||(routeEditor&&b.owner===me))&&b.id!==selected&&distance(s,b)<=RANGE;out+=`<g class="star ${b.visible?'':'unknown-star'}" data-star="${b.id}" role="button" tabindex="0" aria-label="${b.visible?`${b.name}, ${htmlOwnerName(b.owner)}, ${b.ships} naves, ${availableDefense(b)} defesa`:`${b.name}, fora de visão`}" transform="translate(${b.x},${b.y}) scale(${unit*glyph})"><circle r="25" fill="transparent"/><circle class="selection" r="26" fill="none" stroke="#fff" stroke-width="1" opacity="${sel||chosen?1:0}" ${chosen?'stroke-dasharray="4 3"':''}/>${reachable?'<circle r="25" stroke="#4dafdf" fill="none" stroke-dasharray="2 5" opacity=".7"/>':''}<circle r="16" fill="#091725" stroke="${color(b.owner)}" stroke-width="${b.owner===-1||!b.visible?2:5}"/><path d="M0 -11 L3 -4 L10 -5 L6 1 L9 8 L2 6 L-3 11 L-4 4 L-11 2 L-5 -2 L-6 -9 L-1 -6 Z" fill="${b.visible?'#f2f7fd':'#485568'}"/>${prefs.infrastructure&&b.visible&&camera.zoom>=.48?`<text class="star-infrastructure" x="0" y="-29" text-anchor="middle" font-size="12" letter-spacing="3" fill="#dde6ef">${b.economy} ${b.industry} ${b.defense??0}</text>`:''}${prefs.ships&&b.visible&&camera.zoom>=.55?`<text x="21" y="2" font-size="15" fill="white">${b.ships}</text>`:''}${prefs.names&&camera.zoom>=.48?`<text x="21" y="18" font-size="12" fill="#dbe4ed">${b.name}</text>`:''}${online.room&&prefs.names&&b.visible&&b.owner>=0&&camera.zoom>=.65?`<text class="map-owner" x="21" y="32" font-size="10" fill="${color(b.owner)}">${escapeHTML((online.room.members.find(m=>m.owner===b.owner)?.name??ownerName(b.owner)).slice(0,14))}</text>`:''}</g>`;}
svg.innerHTML=out;$('#turnEffects').setAttribute('viewBox',svg.getAttribute('viewBox'));$('#zoomLabel').textContent=Math.round(camera.zoom*100)+'%';$('#mapPrompt').textContent='';$('#pickerBar').hidden=!picking;document.body.classList.toggle('picking',picking);if(picking)$('#pickerTitle').textContent=`${g.stars[selected].name} → destino`;}
function header(){const t=totals(g,me),target=victoryTarget(g);$('#tick').textContent=g.tick+1;$('#credits').textContent=g.credits[me];$('#territory').textContent=t.stars;$('#ships').textContent=t.ships;$('#production').textContent=`+${t.production}`;$('#advance').disabled=g.winner!==null||!!turnPlayback;$('#advance').setAttribute('aria-busy',String(!!turnPlayback));$('#advance').textContent=g.winner===null?'Encerrar turno':'Fim de jogo';$('#fleetCount').textContent=g.fleets.length+g.orders.length||'';$('#mapStatus').textContent=`${g.orders.length} ordens · ${g.fleets.length} frotas · meta: ${target} estrelas`;
$('.factions').innerHTML=`<button data-panel="empire" title="Suas estrelas / meta de vitória"><i class="player-mark" style="border-color:${color(me)}"></i> ${t.stars} / ${target} ✦</button><button data-panel="empire">${g.playerCount} impérios</button>`;
const result=$('#result'),eliminated=t.stars===0&&t.ships===0;result.hidden=(g.winner===null&&!eliminated)||turnPlayback?.phase==='travel';result.textContent=g.winner===null?'Você foi eliminado. Continue os turnos para acompanhar.':g.winner===-1?'Empate: 50% no mesmo turno.':g.winner===me?`Vitória! Você controla ${totals(g,me).stars} de ${g.stars.length} estrelas.`:`${ownerName(g.winner)} venceu: ${g.winningStars} de ${g.stars.length} estrelas.`;}
const disabled=b=>b?'disabled':'';
function starPanel(){const s=g.stars[selected];if(!s.visible){dispatch=false;routeEditor=false;return `<p class="empty fog-message">Fora de visão</p>`;}const own=s.owner===me,ended=g.winner!==null;amount=Math.max(1,Math.min(amount,Math.max(1,s.ships)));if(!own){dispatch=false;routeEditor=false;}
if(routeEditor)return autoRouteForm();
if(dispatch)return dispatchForm();

return `<div class="star-brief"><span><i class="dot" style="background:${color(s.owner)}"></i>${htmlOwnerName(s.owner)}</span><strong>${s.ships} <small>naves</small>${s.defense?` <span class="star-defense" title="Pontos de defesa disponíveis / capacidade">⛨ ${availableDefense(s)}/${defenseCapacity(s)}</span>`:''}</strong></div>${own?`<div class="action-strip star-actions"><button id="dispatchToggle" class="info" ${disabled(ended||s.ships<1)}>➤ Enviar</button><button id="autoRouteToggle" class="route-toggle ${g.autoRoutes.some(r=>r.from===selected&&r.enabled)?'route-set':''}" aria-label="Rota automática">⇄ Rota</button><button id="upgradeDetailsToggle" aria-expanded="${upgradeDetails}" aria-controls="upgradeDetails">${upgradeDetails?"Recolher":"↑ Melhorar"}</button></div>`:''}${own&&upgradeDetails?upgradePanel(s,ended):''}<details class="disclosure star-details"><summary>Detalhes</summary><div class="detail-content"><div class="compact-row"><span>Economia · nível ${s.economy}</span><b>+$${s.owner===-1?0:s.economy*3}/tick</b></div><div class="compact-row"><span>Estaleiro · nível ${s.industry}</span><b>+${s.owner===-1?0:s.industry*2} naves/tick</b></div><div class="compact-row"><span>Defesa · nível ${s.defense??0}</span><b>${availableDefense(s)} / ${defenseCapacity(s)} pontos</b></div><p>Cada nível de defesa comporta 5 pontos. Disponíveis agora: ${availableDefense(s)}; recupera até 2 por turno.</p>${s.owner===-1?'<p>Produz após a conquista.</p>':''}${own&&g.autoRoutes.some(r=>r.from===selected)?`<button id="allRoutes">Ver rotas</button>`:''}</div></details>`;}
function upgradePanel(s,ended){return `<section id="upgradeDetails" aria-label="Melhorias da estrela">${['economy','industry','defense'].map(type=>{const eco=type==='economy',fort=type==='defense',name=eco?'Economia':fort?'Defesa':'Estaleiro',gain=eco?3:fort?5:2,unit=eco?'créditos':'naves',level=s[type]??0,price=cost(s,type),missing=Math.max(0,price-g.credits[me]);return `<div class="upgrade-compact"><details class="disclosure"><summary aria-label="${name}: ganho e custo"><span>${name} <small>nv. ${level}</small></span></summary><div class="detail-content">${fort?`<b>+5 de defesa fixa</b><br>Capacidade: ${defenseCapacity(s)} → ${defenseCapacity(s)+5}<br>Disponível: ${availableDefense(s)} → ${availableDefense(s)+5}<br>Recupera 2 pontos por turno. Absorve perdas antes das naves; funciona mesmo sem frota. Instalações destruídas na conquista.`:`<b>+${gain} ${unit}/tick</b> · ${level*gain} → ${(level+1)*gain}<br>Nível ${level} → ${level+1}.${eco?` Retorno em ${Math.ceil(price/gain)} ticks.`:' Produz a partir do próximo tick.'}`}${missing?`<br>Faltam $${missing}.`:''}<br>Custo: ${eco?20:fort?30:24} × próximo nível.</div></details><button class="success" data-upgrade="${type}" ${disabled(ended||missing>0)} aria-label="Melhorar ${name} por ${price} créditos">↑ $${price}</button></div>`;}).join('')}</section>`;}
function dispatchForm(){const a=g.stars[selected],choices=g.stars.filter(b=>b.id!==a.id&&distance(a,b)<=RANGE);return `<div class="subnav"><button id="cancelDispatch" aria-label="Voltar à estrela">← Estrela</button><span>Enviar frota</span></div><div class="compact-form"><div class="field-row"><label for="destination">Destino</label><select id="destination"><option value="">Selecionar</option>${choices.map(b=>`<option value="${b.id}" ${target===b.id?'selected':''}>${b.name} · ${htmlOwnerName(b.owner)}</option>`).join('')}</select><button id="pickDestination" aria-label="Escolher destino no mapa" title="Escolher no mapa">⊙</button></div><div class="field-row"><label for="amount">Naves</label><div class="number-controls"><input id="amount" aria-label="Quantidade de naves" type="number" min="1" max="${a.ships}" value="${amount}"><button id="half">½</button><button id="all">Tudo</button></div></div><div class="form-footer"><details class="disclosure"><summary>Detalhes</summary><div id="routeInfo" class="detail-content"></div></details><button class="success" id="send" ${disabled(target===null||a.ships<1)}>Enviar</button></div></div>`;}

function routeInfo(){const el=$('#routeInfo');if(!el)return;const a=g.stars[selected],b=g.stars[target];if(b&&!b.visible){el.textContent='Destino fora de visão.';return;}if(!b){el.textContent='Parte ao encerrar o turno.';return;}const eta=travel(a,b),def=b.ships+(b.owner>=0&&b.owner!==me?b.industry*2*eta:0),batteries=defenseAfterTicks(b,eta);el.innerHTML=`Chegada: ${eta} tick${eta>1?'s':''} · turno ${g.tick+eta+1}.<br>${b.owner===me?'Reforço aliado.':`Força estimada: ${def+batteries} (${def} naves + ${batteries} defesa), sem outras ordens.`}<br>Parte ao encerrar o turno. Cancele em Frotas.`;}

function startRouteEditor(from){selected=from;panel='star';dispatch=false;target=null;upgradeDetails=false;routeEditor=true;const r=g.autoRoutes.find(r=>r.owner===me&&r.from===from);autoTarget=r?.to??null;autoReserve=r?.reserve??0;picking=false;if(!r&&g.stars.some(b=>b.owner===me&&b.id!==from&&distance(g.stars[from],b)<=RANGE))beginPicking();else {render();centerOn(g.stars[from]);}}
function beginPicking(){picking=true;render();const a=g.stars[selected],choices=g.stars.filter(b=>b.id===selected||(distance(a,b)<=RANGE&&(!routeEditor||b.owner===me)));const r=$('#map').getBoundingClientRect(),xs=choices.map(b=>b.x),ys=choices.map(b=>b.y),minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys);camera.zoom=Math.max(.25,Math.min(1.3,(r.width-150)/Math.max(150,maxX-minX),(r.height-210)/Math.max(150,maxY-minY)));camera.x=(minX+maxX)/2;camera.y=(minY+maxY)/2;drawMap();$('#pickerList').focus({preventScroll:true});}
function frameSelection(){const a=g.stars[selected],b=g.stars[routeEditor?autoTarget:target];if(!b){centerOn(a);return;}const r=$('#map').getBoundingClientRect(),left=isMobile()?55:panelTargetHeight?$('#panel').getBoundingClientRect().width+65:55,right=r.width-60,top=85,bottom=r.height-(isMobile()?panelTargetHeight:0)-55;camera.zoom=Math.max(.25,Math.min(1.3,(right-left)/Math.max(100,Math.abs(a.x-b.x)),(bottom-top)/Math.max(100,Math.abs(a.y-b.y))));camera.x=(a.x+b.x)/2-((left+right)/2-r.width/2)/camera.zoom;camera.y=(a.y+b.y)/2-((top+bottom)/2-r.height/2)/camera.zoom;drawMap();}
function finishPicking(){picking=false;render();frameSelection();requestAnimationFrame(()=>$(routeEditor?'#autoDestination':'#destination')?.focus({preventScroll:true}));}

function autoRouteForm(){const a=g.stars[selected],current=g.autoRoutes.find(r=>r.owner===me&&r.from===selected),choices=g.stars.filter(b=>b.owner===me&&b.id!==selected&&distance(a,b)<=RANGE);return `<section class="auto-route-editor"><div class="subnav"><button id="closeAutoRoute" aria-label="Voltar à estrela">← Estrela</button><span>Rota automática</span></div>${choices.length?`<div class="compact-form"><div class="field-row"><label for="autoDestination">Destino</label><select id="autoDestination"><option value="">Selecionar</option>${choices.map(b=>`<option value="${b.id}" ${autoTarget===b.id?'selected':''}>${b.name}</option>`).join('')}</select><button id="pickDestination" aria-label="Escolher destino no mapa" title="Escolher no mapa">⊙</button></div><div class="field-row"><label for="autoReserve">Manter</label><input type="number" id="autoReserve" min="0" step="1" value="${Number.isFinite(autoReserve)?autoReserve:''}" aria-label="Naves a manter na origem"><span>naves</span></div><div class="form-footer"><details class="disclosure"><summary>Detalhes</summary><div class="detail-content"><div id="autoPreview"></div><p>Envia o excedente após produzir. Ordens manuais têm prioridade. Reforços recebidos seguem no próximo turno.</p><button id="allRoutes">Ver rotas</button></div></details><button id="saveAutoRoute" class="success" ${disabled(g.winner!==null)}>Salvar</button></div></div>`:'<p class="empty">Sem estrela aliada ao alcance (340 UA).</p>'}${current?`<details class="disclosure route-manage"><summary>${current.enabled?'Rota ativa':'Rota pausada'}</summary><div class="detail-content compact-row"><button data-route-toggle="${current.from}" ${disabled(g.winner!==null||(!current.enabled&&g.stars[current.to].owner!==me))}>${current.enabled?'Pausar':'Retomar'}</button><button data-route-remove="${current.from}" class="danger" ${disabled(g.winner!==null)}>Remover</button></div></details>`:''}</section>`;}

function autoPreview(){const el=$('#autoPreview');if(!el)return;const a=g.stars[selected],b=g.stars[autoTarget],valid=b&&b.owner===me&&b.id!==a.id&&distance(a,b)<=RANGE&&Number.isSafeInteger(autoReserve)&&autoReserve>=0;$('#saveAutoRoute').disabled=!valid||g.winner!==null;el.textContent=valid?`Próximo envio: ${Math.max(0,a.ships+a.industry*2-autoReserve)} naves. Viagem: ${travel(a,b)} tick${travel(a,b)>1?'s':''}.`:'Selecione destino e reserva.';}

function routesList(){const routes=g.autoRoutes.filter(r=>r.owner===me);return `<div class="panel-section route-create"><label for="routeOrigin">Nova rota</label><select id="routeOrigin"><option value="">Origem</option>${g.stars.filter(s=>s.owner===me).map(s=>`<option value="${s.id}">${s.name}</option>`).join('')}</select></div>${routes.length?routes.map(r=>{const a=g.stars[r.from],b=g.stars[r.to],canResume=a.owner===me&&b.owner===me;return `<details class="auto-route-card disclosure"><summary><span>${a.name} → ${b.name}</span><span class="route-status ${r.enabled?'enabled':''}">${r.enabled?'Ativa':'Pausada'}</span></summary><div class="detail-content"><p>Manter ${r.reserve} naves · ${travel(a,b)} tick${travel(a,b)>1?'s':''}</p>${r.pauseReason==='ownership'?'<p class="route-warning">Uma estrela mudou de dono.</p>':''}${r.lastSent?`<p>Último envio: ${r.lastSent.ships} naves · T${r.lastSent.tick+1}</p>`:''}<div class="route-actions"><button data-route-toggle="${r.from}" ${disabled(g.winner!==null||(!r.enabled&&!canResume))}>${r.enabled?'Pausar':'Retomar'}</button><button data-edit-route="${r.from}" ${disabled(a.owner!==me)}>Editar</button><button data-route-remove="${r.from}" class="danger" ${disabled(g.winner!==null)}>Remover</button></div></div></details>`;}).join(''):'<p class="empty">Nenhuma rota.</p>'}<details class="disclosure"><summary>Como funciona</summary><div class="detail-content">Uma rota por origem, entre estrelas suas a até 340 UA. Encadeie A → B → C. A perda de uma estrela pausa a rota. Pausar ou remover mantém as frotas em viagem.</div></details>`;}

function galaxyPanel(){const stars=g.stars.filter(s=>starFilter==='all'||s.owner===me);return `<div class="tabs"><button data-star-filter="all" class="${starFilter==='all'?'active':''}">Todas</button><button data-star-filter="mine" class="${starFilter==='mine'?'active':''}">Suas</button></div><div class="table-wrap"><table><thead><tr><th>Estrela</th><th class="num">Naves</th></tr></thead><tbody>${stars.map(s=>`<tr><td><button data-select-star="${s.id}"><span class="dot" style="background:${color(s.owner)}"></span>${s.name}</button></td><td class="num">${s.visible?s.ships:'—'}</td></tr>`).join('')}</tbody></table></div>`;}

function fleetsPanel(){const tabs=`<div class="tabs"><button data-fleet-filter="all" class="${fleetFilter==='all'?'active':''}">Todas</button><button data-fleet-filter="mine" class="${fleetFilter==='mine'?'active':''}">Suas</button><button data-fleet-filter="routes" class="${fleetFilter==='routes'?'active':''}">Rotas</button></div>`;if(fleetFilter==='routes')return tabs+routesList();const fs=[...g.orders,...g.fleets].filter(f=>fleetFilter==='all'||f.owner===me);return tabs+(fs.length?fs.map(f=>{const pending=g.orders.includes(f);return `<details class="disclosure fleet"><summary><span><i class="dot" style="background:${color(f.owner)}"></i>${Number.isInteger(f.from)?`${g.stars[f.from].name} → ${g.stars[f.to].name}`:'Frota detectada'}</span><b>${f.ships}</b></summary><div class="detail-content"><div class="compact-row"><span>${htmlOwnerName(f.owner)}${f.automatic?' · automática':''}</span><span>${pending?'Aguardando turno':Number.isInteger(f.remaining)?`${f.remaining} ticks · T${g.tick+f.remaining+1}`:'Trajeto desconhecido'}</span></div><div class="route-actions"><button data-center-fleet="${f.id}">Localizar</button>${pending?`<button data-cancel="${f.id}">Cancelar ordem</button>`:''}</div></div></details>`;}).join(''):'<p class="empty">Nenhuma frota.</p>');}

function empirePanel(){const p=totals(g,me),target=victoryTarget(g),ranking=g.credits.map((_,owner)=>({owner,...totals(g,owner)}));return `<div class="empire-brief"><span><b>${p.stars}</b> / ${target} estrelas</span><span><b>${p.ships}</b> naves</span></div><div class="victory-goal"><progress value="${p.stars}" max="${target}" aria-label="Progresso até 50% das estrelas"></progress><span>Meta: ${target} de ${g.stars.length} · 50%</span></div><details class="disclosure"><summary>Produção</summary><div class="detail-content compact-row"><span>+$${p.income}/tick</span><span>+${p.production} naves/tick</span></div></details><details class="disclosure" id="standings"><summary>Placar · ${g.playerCount} impérios</summary><div class="standings-list">${ranking.map(r=>`<details class="disclosure faction-row" data-owner="${r.owner}"><summary><span><i class="dot" style="background:${color(r.owner)}"></i>${htmlOwnerName(r.owner)}</span><span>${r.owner===me?`${r.stars} / ${target} ✦`:`${r.stars} visíveis`}</span></summary><div class="detail-content">${r.owner===me?`${r.ships} naves · +${r.production} naves/tick<br>+$${r.income}/tick`:`${r.ships} naves visíveis · ${online.room?.members.some(m=>m.owner===r.owner&&!m.resigned)?"humano":"bot"}<br>Totais do império desconhecidos.`}</div></details>`).join('')}</div></details><div class="action-strip"><button id="home" class="info">⌂ Localizar</button></div>`;}
function updateSetup(){const count=+$('#playerCount').value;$('#setupSummary').textContent=`Você + ${count-1} bot${count>2?'s':''} · ${count*9} estrelas`;$('#setupGoal').textContent=`Vitória: ${Math.ceil(count*9/2)} estrelas (50%)`;}
function optionsPanel(){const labels={names:'Nomes',ships:'Naves',infrastructure:'Infraestrutura',routes:'Rotas',range:'Alcance'};return `<details class="disclosure"><summary>Exibição do mapa</summary><div>${Object.keys(labels).map(k=>`<label class="switch-row" for="toggle-${k}"><span>${labels[k]}</span><input class="switch" id="toggle-${k}" data-pref="${k}" type="checkbox" role="switch" ${prefs[k]?'checked':''}></label>`).join('')}<p class="detail-content">Nomes e infraestrutura aparecem ao aproximar. Infraestrutura: economia · estaleiro · defesa (níveis).</p></div></details><details class="disclosure"><summary>Atalhos</summary><div class="detail-content">G: estrelas · F: frotas · E: eventos<br>H: império · O: opções · Z: enquadrar<br>+/−: zoom · Esc: voltar ou fechar</div></details><div class="action-strip"><button id="showHelp" class="info help-button">Como jogar</button><button id="restart">Nova partida</button></div>`;}

const combatNumber=n=>Number(n.toFixed(2)).toLocaleString('pt-BR');
function battleCalculation(b,who){
 if(b.rule==='moderate-duels')return `<p>Forças divididas igualmente entre os adversários. Duelos simultâneos; sobreviventes reagrupados a cada rodada, dentro do mesmo tick. Defesa dividida junto das naves e consumida primeiro em cada duelo. Frações mantidas até o resultado final; valores abaixo aproximados.</p>${b.rounds.map(r=>`<details class="disclosure combat-round"><summary>Rodada ${r.number} · ${r.duels.length} duelo${r.duels.length===1?'':'s'}</summary><div class="detail-content">${r.participants.map(f=>`<div>${who(f.owner)}: ${combatNumber(f.force)} ÷ ${r.participants.length-1} = ${combatNumber(f.shareForce)} por duelo (${combatNumber(f.shareShips)} naves + ${combatNumber(f.shareDefense)} defesa).</div>`).join('')}${r.duels.map(d=>`<div class="combat-duel"><b>${who(d.left)} × ${who(d.right)}</b><br>${combatNumber(d.leftForce)} × ${combatNumber(d.rightForce)} → ${d.winner===null?'empate · 0':`${who(d.winner)}: ${combatNumber(d.ships)} naves + ${combatNumber(d.defense)} defesa`}<br>${combatNumber(Math.max(d.leftForce,d.rightForce))} − ${combatNumber(Math.min(d.leftForce,d.rightForce))}² ÷ ${combatNumber(Math.max(d.leftForce,d.rightForce))} ≈ ${combatNumber(d.remainingForce)}</div>`).join('')}<p>Reagrupamento: ${r.survivors.map(f=>`${who(f.owner)} ${combatNumber(f.force)}`).join(' · ')}.</p></div></details>`).join('')}<p>Resultado final: ${b.remaining} naves + ${b.defenseAfter} defesa.${b.tied?' Nenhum sobrevivente; o controle anterior permanece.':''}</p>`;
 if(b.rule==='moderate-largest')return `Relatório histórico: regra anterior, considerando apenas o maior adversário.<br>${b.tied?'Empate na maior força; o controle anterior permaneceu.':`${b.largestForce} − ${b.oppositionForce}² ÷ ${b.largestForce} ≈ ${b.remainingForce} de força restante.`}`;
 return 'Relatório histórico: regra anterior de troca direta de naves, considerando a soma dos adversários.';
}
function battleReport(b){const who=o=>o===-1?'Milícia neutra':htmlOwnerName(o),modern=['moderate-largest','moderate-duels'].includes(b.rule),defender=b.forces.find(f=>f.owner===b.defender);return `<details class="battle-report" data-report="${b.id}" ${battleFocus===b.id?'open':''}><summary><span>${b.starName} <small>· turno ${b.tick+1}</small></span><span>${modern&&b.tied?'Empate':!modern&&b.remaining===0?'Sem sobreviventes':b.captured?'Conquista':'Defesa'}</span></summary><div class="battle-outcome">${who(b.ownerAfter)} ${b.captured?'conquistou':'manteve'} a estrela · ${b.remaining} naves${modern?` · ${b.defenseAfter} defesa`:''}.</div><div class="table-wrap"><table class="battle-table"><thead><tr><th>Lado</th><th class="num">Naves</th><th class="num">Perdas</th><th class="num">Após</th></tr></thead><tbody>${b.forces.map(f=>`<tr><td><span class="dot" style="background:${color(f.owner)}"></span>${who(f.owner)}<small>${modern?`Força ${f.force} · defesa ${f.defense}`:`${f.owner===b.defender?'Defensor':'Atacante'} · força ${f.strength} por nave`}</small></td><td class="num">${f.total}</td><td class="num loss">−${f.lost}</td><td class="num">${f.survived}</td></tr>`).join('')}</tbody></table></div>${modern?`<div class="battle-breakdown">Defesa de ${who(b.defender)}: ${defender?.defense??0} → ${b.defenseAfter} pontos.</div>`:''}<details class="disclosure battle-calculation"><summary>Cálculo</summary><div class="detail-content">${battleCalculation(b,who)}<p>Força 1 por nave. A guarnição inclui a produção deste tick. Frotas do mesmo império que chegam juntas são somadas.</p>${b.forces.map(f=>`<div>${who(f.owner)}: ${f.garrison} em órbita + ${f.arrivals} em chegadas.</div>`).join('')}</div></details><button class="battle-locate" data-center="${b.starId}">⊙ Localizar ${b.starName}</button></details>`;}
function eventsPanel(){return `<div class="tabs"><button data-events-tab="all" class="${eventsTab==='all'?'active':''}">Todos</button><button data-events-tab="battles" class="${eventsTab==='battles'?'active':''}">Batalhas (${g.battles.length})</button></div>${eventsTab==='battles'?(g.battles.length?g.battles.map(battleReport).join(''):'<p class="empty">Nenhuma batalha registrada.</p>'):g.logs.map(l=>`<details class="disclosure log ${l.kind}"><summary><time>T${l.tick+1}</time><span>${l.text.length>52?l.text.slice(0,49)+'…':l.text}</span></summary><div class="detail-content">${l.text}${l.battleId&&g.battles.some(b=>b.id===l.battleId)?`<button class="report-link" data-battle="${l.battleId}">Relatório</button>`:''}</div></details>`).join('')}`;}
const reducedMotion=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
let panelRevision=0,lastPanelKey=null,panelTargetHeight=0;
function motion(el,frames,duration=300,done=()=>{}){el.getAnimations().forEach(a=>a.cancel());if(reducedMotion()){done();return;}const a=el.animate(frames,{duration,easing:'cubic-bezier(.22,.75,.25,1)'});a.finished.then(done,()=>{});}
function renderPanel(){const surface=$('#panel'),body=$('#panelBody'),revision=++panelRevision,wasHidden=surface.hidden,oldHeight=surface.getBoundingClientRect().height,oldKey=lastPanelKey;surface.getAnimations().forEach(a=>a.cancel());document.querySelectorAll('[data-panel]').forEach(b=>{b.classList.toggle('active',b.dataset.panel===panel);b.setAttribute('aria-pressed',String(b.dataset.panel===panel));});if(!panel||picking){lastPanelKey=null;panelTargetHeight=0;surface.inert=true;if(!wasHidden)motion(surface,[{transform:'translateY(0)',opacity:1},{transform:isMobile()?'translateY(100%)':'translateY(60px)',opacity:0}],280,()=>{if(panelRevision===revision&&(!panel||picking)){surface.hidden=true;surface.inert=false;document.body.classList.remove('panel-open');}});else document.body.classList.remove('panel-open');return;}
surface.hidden=false;surface.inert=false;document.body.classList.add('panel-open');$('#centerStar').hidden=panel!=='star';const title={star:g.stars[selected].name,galaxy:'Galáxia',fleets:'Frotas',empire:'Seu império',events:'Eventos',options:'Opções'};$('#panelTitle').textContent=title[panel];const key=panel==='star'?`star-${selected}-${routeEditor?'route':dispatch?'send':upgradeDetails?'upgrade':'overview'}`:panel;const scroll=key===oldKey?body.scrollTop:0;body.innerHTML=panel==='star'?starPanel():panel==='galaxy'?galaxyPanel():panel==='fleets'?fleetsPanel():panel==='empire'?empirePanel():panel==='options'?optionsPanel():eventsPanel();body.scrollTop=scroll;const expandable=canExpandStar();$('#sheetHandle').setAttribute('aria-label',expandable?(upgradeDetails?'Recolher melhorias':'Mostrar melhorias'):'Fechar painel');if(expandable)$('#sheetHandle').setAttribute('aria-expanded',String(upgradeDetails));else $('#sheetHandle').removeAttribute('aria-expanded');routeInfo();autoPreview();lastPanelKey=key;panelTargetHeight=surface.getBoundingClientRect().height;
if(wasHidden||oldKey===null)motion(surface,[{transform:isMobile()?'translateY(100%)':'translateY(60px)',opacity:0},{transform:'translateY(0)',opacity:1}]);else {if(Math.abs(oldHeight-panelTargetHeight)>1)motion(surface,[{height:`${oldHeight}px`},{height:`${panelTargetHeight}px`}],200);if(key!==oldKey)motion(body,[{transform:'translateY(12px)',opacity:.3},{transform:'translateY(0)',opacity:1}],180);}}
document.addEventListener('click',e=>{const summary=e.target.closest('summary');if(!summary)return;const d=summary.parentElement;if(d.tagName!=='DETAILS')return;e.preventDefault();const closing=d.dataset.expanding==='true'||(d.open&&d.dataset.expanding!=='false'),start=d.getBoundingClientRect().height;d.getAnimations().forEach(a=>a.cancel());d.style.overflow='hidden';if(!closing)d.open=true;const end=closing?summary.getBoundingClientRect().height:d.getBoundingClientRect().height;d.dataset.expanding=String(!closing);motion(d,[{height:`${start}px`},{height:`${end}px`}],260,()=>{d.open=!closing;delete d.dataset.expanding;d.style.overflow='';});});
function showDialog(id){const d=$(id);d.inert=false;if(!d.open)d.showModal();motion(d,[{transform:isMobile()?'translateY(100%)':'translateY(60px)',opacity:0},{transform:'translateY(0)',opacity:1}]);}
function closeDialog(id){const d=typeof id==='string'?$(id):id;if(!d.open)return;d.inert=true;motion(d,[{transform:'translateY(0)',opacity:1},{transform:isMobile()?'translateY(100%)':'translateY(60px)',opacity:0}],280,()=>{d.close();d.inert=false;});}
document.querySelectorAll('dialog').forEach(d=>{d.addEventListener('cancel',e=>{e.preventDefault();closeDialog(d);});d.querySelector('form[method="dialog"]')?.addEventListener('submit',e=>{e.preventDefault();closeDialog(d);});});

function canExpandStar(){return panel==='star'&&!picking&&!dispatch&&!routeEditor&&g.stars[selected].owner===me;}
function setStarExpanded(expanded){if(!canExpandStar()||upgradeDetails===expanded)return;upgradeDetails=expanded;render();centerOn(g.stars[selected]);}
let sheetDrag=null,suppressSheetClick=false;
$('.panel-heading').addEventListener('pointerdown',e=>{if(!isMobile()||e.button!==0||(e.target.closest('button')&&e.target.closest('button').id!=='sheetHandle'))return;suppressSheetClick=false;sheetDrag={id:e.pointerId,x:e.clientX,y:e.clientY};(e.target.closest('#sheetHandle')||e.currentTarget).setPointerCapture(e.pointerId);});
$('.panel-heading').addEventListener('pointerup',e=>{if(sheetDrag?.id!==e.pointerId)return;const dy=e.clientY-sheetDrag.y,dx=e.clientX-sheetDrag.x;sheetDrag=null;if(Math.abs(dy)<32||Math.abs(dy)<=Math.abs(dx))return;suppressSheetClick=true;if(dy<0)setStarExpanded(true);else if(canExpandStar()&&upgradeDetails)setStarExpanded(false);else closePanel();});
$('.panel-heading').addEventListener('pointercancel',()=>{sheetDrag=null;});
$('.panel-heading').addEventListener('click',e=>{if(suppressSheetClick){suppressSheetClick=false;e.preventDefault();e.stopPropagation();}},true);
$('#sheetHandle').addEventListener('click',()=>{if(canExpandStar())setStarExpanded(!upgradeDetails);else closePanel();});
function render(){g=online.room?.game??playerView(world,0);header();renderPanel();drawMap();if(online.room){$('#advance').disabled=online.busy||!online.room.started||!online.room.canPlay||g.winner!==null;$('#advance').textContent=online.room.ready?'Desfazer pronto':'Confirmar turno';}}
function dispatchClose(){picking=false;dispatch=false;target=null;render();}
function showIncome(income){const badge=$('#creditGain');clearTimeout(creditTimer);badge.getAnimations().forEach(a=>a.cancel());badge.textContent=`+$${income}`;badge.hidden=false;if(!reducedMotion())badge.animate([{opacity:0,transform:'translateY(5px)'},{opacity:1,transform:'translateY(0)',offset:.15},{opacity:1,transform:'translateY(-3px)',offset:.7},{opacity:0,transform:'translateY(-9px)'}],{duration:1100,easing:'ease-out'});creditTimer=setTimeout(()=>{badge.hidden=true;},1100);}
function stopTurnEffects(){cancelAnimationFrame(turnFrame);turnFrame=0;turnPlayback=null;$('#turnEffects').replaceChildren();$('#game').removeAttribute('data-turn-phase');clearTimeout(creditTimer);$('#creditGain').getAnimations().forEach(a=>a.cancel());$('#creditGain').hidden=true;}
function announceTurn(){const battles=g.battles.filter(b=>b.tick===g.tick).length;notify(g.winner===null?`Turno ${g.tick+1}${battles?` · ${battles} batalha${battles>1?'s':''}`:''}`:g.winner===me?'Vitória!':'Partida encerrada.');}
function finishTurnEffects(){cancelAnimationFrame(turnFrame);turnFrame=0;turnPlayback=null;$('#turnEffects').replaceChildren();$('#game').removeAttribute('data-turn-phase');header();drawMap();announceTurn();}
function playTurnEffects(movements,before){
 movements=movements.filter(f=>movementVisible(before,me,f));
 const calm=reducedMotion(),battles=g.battles.filter(b=>b.tick===g.tick),travelMs=!calm&&movements.length?620:0,totalMs=travelMs+(battles.length?420:180),overlay=$('#turnEffects');
 turnPlayback={phase:travelMs?'travel':'combat',view:before};render();$('#game').dataset.turnPhase=turnPlayback.phase;
 overlay.innerHTML=movements.map(f=>`<g class="turn-fleet" data-moving-fleet="${f.id}" ${f.owner===me?`data-from="${f.from}" data-to="${f.to}" data-automatic="${!!f.automatic}"`: ''} stroke="${color(f.owner)}"><path d="M-22 0 H-10" stroke-width="2" opacity=".55"/><path d="M9 0 L-7 -6 L-3 0 L-7 6 Z" fill="white" stroke-width="2"/></g>`).join('')+battles.map(b=>`<g class="battle-pulse" data-battle-star="${b.starId}" visibility="hidden"><circle fill="none" stroke="#ffbe78" stroke-width="2"/><circle class="battle-glow" r="22" fill="#ffae67" opacity=".18"/><path d="M-5 -5 L5 5 M-5 5 L5 -5" stroke="#fff1d9" stroke-width="2"/></g>`).join('');
 const ships=[...overlay.querySelectorAll('.turn-fleet')],pulses=[...overlay.querySelectorAll('.battle-pulse')],start=performance.now();
 function frame(now){if(!turnPlayback)return;const elapsed=now-start,moving=elapsed<travelMs,progress=travelMs?Math.min(1,elapsed/travelMs):1,unit=1/camera.zoom;
  if(!moving&&turnPlayback.phase==='travel'){turnPlayback.phase='combat';$('#game').dataset.turnPhase='combat';header();drawMap();}
  ships.forEach((node,i)=>{node.style.display=moving?'':'none';if(!moving)return;const f=movements[i],a=g.stars[f.from],b=g.stars[f.to],ratio=1-f.remaining/f.total+progress/f.total;if(f.owner!==me&&!pointVisible(before,me,{x:a.x+(b.x-a.x)*ratio,y:a.y+(b.y-a.y)*ratio})){node.style.display='none';return;}node.setAttribute('transform',`translate(${a.x+(b.x-a.x)*ratio},${a.y+(b.y-a.y)*ratio}) scale(${unit}) rotate(${Math.atan2(b.y-a.y,b.x-a.x)*180/Math.PI})`);});
  const pulse=Math.max(0,Math.min(1,(elapsed-travelMs)/420));pulses.forEach((node,i)=>{node.setAttribute('visibility',moving?'hidden':'visible');const b=g.stars[battles[i].starId];node.setAttribute('transform',`translate(${b.x},${b.y}) scale(${unit})`);node.setAttribute('opacity',calm?'.85':String(1-pulse));node.querySelector('circle').setAttribute('r',calm?28:22+26*pulse);});
  if(elapsed>=totalMs){finishTurnEffects();return;}turnFrame=requestAnimationFrame(frame);
 }
 frame(start);
}
async function doAdvance(){if(online.room){try{await online.command({type:"ready",ready:!online.room.ready});}catch(e){notify(e.message);}return;}if(turnPlayback||g.winner!==null)return;try{const movements=[],before=playerView(world,0),credits=world.credits[me];advance(world,true,movements);g=playerView(world,0);save();clearTimeout(toastTimer);$('#toast').classList.remove('show');picking=false;routeEditor=false;dispatch=false;target=null;playTurnEffects(movements,before);showIncome(g.credits[me]-credits);}catch(e){stopTurnEffects();render();notify(e.message);}}
document.addEventListener('visibilitychange',()=>{if(document.hidden&&turnPlayback)finishTurnEffects();});
function home(){const s=g.stars.find(s=>s.owner===me);if(s)selectStar(s.id);else notify('Você não possui estrelas. Suas frotas ainda podem conquistar uma.');}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const data=b.dataset;if(data.editRoute!==undefined){startRouteEditor(+data.editRoute);return;}if(data.routeToggle!==undefined){act(async()=>{const r=g.autoRoutes.find(r=>r.owner===me&&r.from===+data.routeToggle);if(!r)throw Error('Rota indisponível.');if(r.enabled)await pauseAutoRoute(world,me,r.from);else await setAutoRoute(world,me,r.from,r.to,r.reserve);});return;}if(data.routeRemove!==undefined){act(async()=>{await removeAutoRoute(world,me,+data.routeRemove);notify('Rota removida.');});return;}if(data.eventsTab){eventsTab=data.eventsTab;battleFocus=null;renderPanel();return;}if(data.battle){eventsTab='battles';battleFocus=data.battle;panel='events';render();document.querySelector(`[data-report="${data.battle}"]`)?.scrollIntoView({block:'nearest'});return;}if(data.panel){openPanel(data.panel);return;}if(data.selectStar!==undefined){selectStar(+data.selectStar);return;}if(data.center!==undefined){centerOn(g.stars[+data.center]);return;}if(data.centerFleet!==undefined){const f=[...g.orders,...g.fleets].find(f=>f.id===+data.centerFleet);if(f){centerOn(fleetPosition(g,f));}return;}if(data.upgrade){act(async()=>{await upgrade(world,me,selected,data.upgrade);notify(data.upgrade==='economy'?'Economia: +3 créditos/tick.':data.upgrade==='defense'?'Defesa: +5 pontos.':'Estaleiro: +2 naves/tick.');});return;}if(data.cancel){act(async()=>await cancel(world,+data.cancel));return;}if(data.starFilter){starFilter=data.starFilter;renderPanel();return;}if(data.fleetFilter){fleetFilter=data.fleetFilter;renderPanel();return;}
switch(b.id){case 'pickDestination':beginPicking();break;case 'pickerList':case 'cancelPicker':finishPicking();break;case 'autoRouteToggle':if(routeEditor){routeEditor=false;render();}else startRouteEditor(selected);break;case 'closeAutoRoute':routeEditor=false;render();break;case 'allRoutes':routeEditor=false;fleetFilter='routes';openPanel('fleets');break;case 'saveAutoRoute':act(async()=>{await setAutoRoute(world,me,selected,autoTarget,autoReserve);routeEditor=false;notify('Rota salva.');});break;case 'closePanel':closePanel();break;case 'centerStar':centerOn(g.stars[selected]);break;case 'menu-toggle':openPanel('options');break;case 'upgradeDetailsToggle':setStarExpanded(!upgradeDetails);break;case 'dispatchToggle':routeEditor=false;dispatch=!dispatch;if(dispatch){upgradeDetails=false;amount=g.stars[selected].ships;}target=null;render();if(dispatch&&isMobile())centerOn(g.stars[selected]);break;case 'cancelDispatch':case 'cancelDispatchBottom':dispatchClose();break;case 'half':amount=Math.max(1,Math.floor(g.stars[selected].ships/2));renderPanel();break;case 'all':amount=g.stars[selected].ships;renderPanel();break;case 'send':act(async()=>{const f=await queue(world,me,selected,target,amount);dispatch=false;target=null;notify(`Ordem: ${f.ships} → ${g.stars[f.to].name}.`);});break;case 'advance':doAdvance();break;case 'fit':closePanel();fit();break;case 'zoomIn':zoomBy(1.25);break;case 'zoomOut':zoomBy(.8);break;case 'homeMap':case 'home':home();break;case 'help':case 'showHelp':showDialog('#helpDialog');break;case 'helpDone':closeDialog('#helpDialog');break;case 'restart':if(online.room){online.open();break;}showDialog('#newDialog');break;case 'keepGame':closeDialog('#newDialog');break;case 'newGame':stopTurnEffects();picking=false;world=newGame(+$('#playerCount').value);selected=world.stars.find(s=>s.owner===me).id;target=null;dispatch=false;routeEditor=false;upgradeDetails=false;fleetFilter='all';panel=null;eventsTab='all';battleFocus=null;amount=54;save();render();startView();closeDialog('#newDialog');break;}});
document.addEventListener('change',e=>{if(e.target.id==='playerCount')updateSetup();if(e.target.id==='autoDestination'){autoTarget=e.target.value===''?null:+e.target.value;autoPreview();drawMap();}if(e.target.id==='routeOrigin'&&e.target.value!=='')startRouteEditor(+e.target.value);if(e.target.id==='destination'){target=e.target.value===''?null:+e.target.value;$('#send').disabled=target===null;routeInfo();drawMap();}if(e.target.dataset.pref){prefs[e.target.dataset.pref]=e.target.checked;try{localStorage.setItem(UIKEY,JSON.stringify(prefs));}catch{}drawMap();}});
document.addEventListener('input',e=>{if(e.target.id==='autoReserve'){autoReserve=e.target.value===''?NaN:+e.target.value;autoPreview();}if(e.target.id==='amount'||e.target.id==='range'){amount=+e.target.value;const other=e.target.id==='amount'?$('#range'):$('#amount');if(other)other.value=amount;}});
let drag=null,ignoreClick=false;const pointers=new Map();let pinch=null;
const map=$('#map');map.addEventListener('pointerdown',e=>{if(e.button!==0)return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});map.setPointerCapture(e.pointerId);drag={x:e.clientX,y:e.clientY,cx:camera.x,cy:camera.y,moved:false,starId:e.target.closest('[data-star]')?.dataset.star};if(pointers.size===2){const a=[...pointers.values()];pinch={distance:Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y)};ignoreClick=true;}map.classList.add('dragging');});
map.addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2&&pinch){const a=[...pointers.values()],d=Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y);zoomBy(d/Math.max(1,pinch.distance),{x:(a[0].x+a[1].x)/2,y:(a[0].y+a[1].y)/2});pinch.distance=d;return;}if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.hypot(dx,dy)>5)drag.moved=true;if(drag.moved){camera.x=drag.cx-dx/camera.zoom;camera.y=drag.cy-dy/camera.zoom;drawMap();}});
map.addEventListener('pointerup',e=>{const moved=drag?.moved||ignoreClick,clickedStar=drag?.starId;const point={x:e.clientX,y:e.clientY};pointers.delete(e.pointerId);pinch=null;drag=null;map.classList.remove('dragging');if(!moved&&clickedStar!==undefined){pickStar(+clickedStar);}else if(!moved){const r=map.getBoundingClientRect(),wx=camera.x+(point.x-r.left-r.width/2)/camera.zoom,wy=camera.y+(point.y-r.top-r.height/2)/camera.zoom;const s=[...g.stars].sort((a,b)=>Math.hypot(a.x-wx,a.y-wy)-Math.hypot(b.x-wx,b.y-wy))[0];if(s&&Math.hypot(s.x-wx,s.y-wy)*camera.zoom<30)pickStar(s.id);else {const f=[...g.fleets,...g.orders].find(f=>{const p=fleetPosition(g,f);return Math.hypot(p.x-wx,p.y-wy)*camera.zoom<20;});if(f&&!picking){panel='fleets';dispatch=false;routeEditor=false;render();}}}if(!pointers.size)ignoreClick=false;});
map.addEventListener('pointercancel',()=>{pointers.clear();drag=null;pinch=null;ignoreClick=false;map.classList.remove('dragging');});map.addEventListener('wheel',e=>{e.preventDefault();zoomBy(e.deltaY>0?.9:1.1,{x:e.clientX,y:e.clientY});},{passive:false});
function pickStar(id){if(routeEditor){const a=g.stars[selected],b=g.stars[id];if(id===selected||b.owner!==me||distance(a,b)>RANGE){notify('Escolha outra estrela sua a até 340 UA.');return;}autoTarget=id;if(picking)finishPicking();else render();}else if(dispatch){const s=g.stars[selected],t=g.stars[id];if(id===selected||distance(s,t)>RANGE){notify('Escolha outra estrela dentro do alcance de 340 UA.');return;}target=id;if(picking)finishPicking();else render();}else selectStar(id);}
map.addEventListener('keydown',e=>{const s=e.target.closest('[data-star]'),f=e.target.closest('[data-fleet]');if((e.key==='Enter'||e.key===' ')&&(s||f)){e.preventDefault();e.stopPropagation();if(s)pickStar(+s.dataset.star);else openPanel('fleets');}});
document.addEventListener('keydown',e=>{if(e.target.matches('input,select,textarea')||document.querySelector('dialog[open]'))return;if(e.key==='Escape'){if(picking)finishPicking();else closePanel();return;}const p={g:'galaxy',f:'fleets',e:'events',h:'empire',o:'options'}[e.key.toLowerCase()];if(p){e.preventDefault();openPanel(p);}if(e.key==='z'){closePanel();fit();}if(e.key==='+'||e.key==='=')zoomBy(1.25);if(e.key==='-')zoomBy(.8);});window.addEventListener('resize',()=>{drawMap();});

const online=new Online(room=>{
 const previousTick=g?.tick,changedGame=room?.game&&(!g||g.playerCount!==room.game.playerCount||!onlineStarted||onlineRoomCode!==room.code);
 me=room?.started?room.owner:0;
 if(room?.game){if(changedGame||previousTick!==room.game.tick){stopTurnEffects();picking=false;routeEditor=false;dispatch=false;target=null;panel=null;selected=room.game.stars.find(s=>s.owner===me)?.id??0;}}
 else if(onlineStarted){selected=world.stars.find(s=>s.owner===0)?.id??0;panel=null;}
 onlineStarted=!!room?.started;onlineRoomCode=room?.code??null;render();if(changedGame)startView();
},notify);
let onlineStarted=false,onlineRoomCode=null;
document.addEventListener('open-online-battle',e=>{if(!g.battles.some(b=>b.id===e.detail))return;panel='events';eventsTab='battles';battleFocus=e.detail;dispatch=false;routeEditor=false;render();});
const queue=async(w,o,from,to,ships)=>online.room?online.action({type:'send',from,to,ships}):localqueue(w,o,from,to,ships);
const cancel=async(w,id)=>online.room?online.action({type:'cancel',id}):localcancel(w,id);
const upgrade=async(w,o,star,type)=>online.room?online.action({type:'upgrade',star,upgrade:type}):localupgrade(w,o,star,type);
const setAutoRoute=async(w,o,from,to,reserve)=>online.room?online.action({type:'route',from,to,reserve}):localsetAutoRoute(w,o,from,to,reserve);
const pauseAutoRoute=async(w,o,from)=>online.room?online.action({type:'pause',from}):localpauseAutoRoute(w,o,from);
const removeAutoRoute=async(w,o,from)=>online.room?online.action({type:'remove',from}):localremoveAutoRoute(w,o,from);

updateSetup();render();startView();save();online.init();initLanding(online);
// Browser agent actions share the visible game's state and validation.
if(document.modelContext?.registerTool){const life=new AbortController();const register=t=>{try{Promise.resolve(document.modelContext.registerTool(t,{signal:life.signal})).catch(()=>{});}catch{}};register({name:'read_game',description:'Read the current turn, stars, resources, fleets and reserved orders.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>structuredClone(g)});register({name:'reserve_fleet',description:'Reserve player ships for departure at turn end. Does not advance the turn.',inputSchema:{type:'object',properties:{from:{type:'integer'},to:{type:'integer'},ships:{type:'integer',minimum:1}},required:['from','to','ships'],additionalProperties:false},execute:async input=>{if(!input||!Number.isInteger(input.from)||!Number.isInteger(input.to)||!Number.isInteger(input.ships))throw Error('Invalid fleet.');const result=await queue(world,me,input.from,input.to,input.ships);save();render();return result;}});register({name:'end_turn',description:'Commit all reserved orders and advance production, the opponent, travel and battles by one tick.',inputSchema:{type:'object',properties:{},additionalProperties:false},execute:async()=>{if(turnPlayback)throw Error('Aguarde a transição do turno.');await doAdvance();return {tick:g.tick,winner:g.winner,player:totals(g,me)};}});register({name:'set_auto_route',description:'Configure and activate one recurring allied reinforcement route, keeping a ship reserve at its origin. Ships depart on turn end after production.',inputSchema:{type:'object',properties:{from:{type:'integer'},to:{type:'integer'},reserve:{type:'integer',minimum:0}},required:['from','to','reserve'],additionalProperties:false},execute:async input=>{if(!input)throw Error('Invalid route.');const result=await setAutoRoute(world,me,input.from,input.to,input.reserve);save();render();return result;}});window.addEventListener('pagehide',()=>life.abort(),{once:true});}
